package swagger

import (
	"fmt"
	"reflect"
	"strings"
	"time"

	"github.com/nexsoft-git/nexcommon/dto/out"
	"github.com/nexsoft-git/nexcommon/util/validator/tag_validator"
)

func (s *SwaggerAutoGenerateDocument) DocumentDescription(desc string) *SwaggerAutoGenerateDocument {
	s.Info.Description = desc
	return s
}

func (s *SwaggerAutoGenerateDocument) DocumentTitle(title string) *SwaggerAutoGenerateDocument {
	s.Info.Title = title
	return s
}

func (s *SwaggerAutoGenerateDocument) StandardDocumentTitle(resource string, app string) *SwaggerAutoGenerateDocument {
	s.Info.Title = fmt.Sprintf("API Documentation of service %s (%s)", resource, app)
	return s
}

func (s *SwaggerAutoGenerateDocument) AppVersion(version string) *SwaggerAutoGenerateDocument {
	s.Info.Version = version
	return s
}

func ReadResponse(
	isFileResult bool,
	name string,
	dto interface{},
) RequestBodyContentWithDescription {

	var result RequestBodyContentWithDescription
	result.Description = name
	result.Content = make(map[string]SwaggerContent)
	contentData := make(map[string]interface{})
	var dtoType reflect.Type

	contentType := "application/json"

	if isFileResult {
		contentType = "application/octet-stream"

		temp := SwaggerContent{}

		temp.Schema.Type = "string"
		temp.Schema.Format = "binary"

		result.Content[contentType] = temp

		return result
	}

	reflectType := reflect.TypeOf(dto)
	reflectValue := reflect.ValueOf(dto)

	if reflectType.Kind() == reflect.Ptr {
		reflectType = reflectType.Elem()
		reflectValue = reflectValue.Elem()
	}

	for i := 0; i < reflectType.NumField(); i++ {

		contentField := make(map[string]interface{})
		currentField := reflectType.Field(i)
		currentValue := reflectValue.FieldByName(currentField.Name)
		jsonField := currentField.Tag.Get("json")

		if currentField.Type.Kind() == reflect.Struct {
			val := currentValue

			if currentValue.Kind() == reflect.Ptr {
				val = val.Addr()
			}

			newDTO := val.Interface()

			prop := ReadResponse(isFileResult, jsonField, newDTO)
			temp := make(map[string]interface{})
			contentField["type"] = "object"

			for keys := range prop.Content {
				for properties := range prop.Content[keys].Schema.Properties {
					temp[properties] = prop.Content[keys].Schema.Properties[properties]
				}
			}
			contentField["properties"] = temp
		} else if currentField.Type.Kind() == reflect.Interface {
			if !currentValue.IsNil() {
				newDTO := currentValue.Elem().Interface()
				dtoType = reflect.TypeOf(newDTO)

				if dtoType.Kind().String() == reflect.Struct.String() {
					prop := ReadResponse(isFileResult, jsonField, newDTO)
					temp := make(map[string]interface{})
					contentField["type"] = "object"

					for keys := range prop.Content {
						for properties := range prop.Content[keys].Schema.Properties {
							temp[properties] = prop.Content[keys].Schema.Properties[properties]
						}
					}

					contentField["properties"] = temp
				} else {
					currentValue = currentValue.Elem()
				}
			}
		} else if currentField.Type.Kind() == reflect.Map {
			val := currentField.Type.Elem()
			obj := reflect.New(val)

			temp := make(map[string]interface{})

			if obj.Elem().Kind() != reflect.Interface {
				prop := ReadResponse(isFileResult, jsonField, obj.Interface())
				contentField["type"] = "object"
				for keys := range prop.Content {
					for properties := range prop.Content[keys].Schema.Properties {
						temp[properties] = prop.Content[keys].Schema.Properties[properties]
					}
				}
			}

			contentField["properties"] = temp
		}

		if basic.ValidateStringContainInStringArray(tag_validator.IntType, currentField.Type.String()) {
			contentField["type"] = "integer"
			contentField["format"] = currentField.Type.String()
		} else if basic.ValidateStringContainInStringArray(tag_validator.FloatType, currentField.Type.String()) {
			contentField["type"] = "number"
			contentField["format"] = "float"
		} else if reflect.String.String() == currentField.Type.String() {
			contentField["type"] = "string"
		} else if currentField.Type.String() == "time.Time" || currentField.Type.String() == "out.DefaultTime" {
			contentField["type"] = "string"
			contentField["format"] = "date-time"

			if currentField.Type.String() == "out.DefaultTime" {
				curTime := currentValue.Interface().(out.DefaultTime)
				contentField["example"] = curTime
			} else {
				curTime := currentValue.Interface().(time.Time)
				contentField["example"] = curTime
			}
		} else if reflect.Bool.String() == currentField.Type.String() {
			contentField["type"] = "boolean"
		} else if currentValue.Kind() == reflect.Slice {
			var fieldType reflect.Type
			if dtoType != nil {
				fieldType = dtoType.Elem()
			} else {
				fieldType = currentField.Type.Elem()
			}

			contentField["type"] = "array"
			items := make(map[string]interface{})
			propData := make(map[string]interface{})
			if fieldType.Kind().String() == reflect.Struct.String() {
				obj := reflect.New(fieldType).Interface()

				prop := ReadResponse(isFileResult, jsonField, obj)
				contentField["type"] = "array"

				for keys := range prop.Content {
					for properties := range prop.Content[keys].Schema.Properties {
						propData[properties] = prop.Content[keys].Schema.Properties[properties]
					}
				}

				items["type"] = "object"
				items["properties"] = propData
			} else {
				dataType, format := readFieldType(fieldType.String())

				items["type"] = dataType
				if format != "" {
					items["format"] = format
				}

				if !currentValue.IsNil() {
					contentField["example"] = currentValue.Interface()
				}

			}

			contentField["items"] = items
		}

		if jsonField != "" {
			contentData[jsonField] = contentField
		} else {
			if contentField["properties"] != nil {
				field, valid := contentField["properties"].(map[string]interface{})
				if valid {
					for keys := range field {
						contentData[keys] = field[keys]
					}
				}
			}
		}
	}

	temp := SwaggerContent{}
	temp.Schema.Properties = contentData
	result.Content[contentType] = temp

	return result
}

func readFieldType(
	fieldElem string,
) (
	dataType string,
	format string,
) {
	if basic.ValidateStringContainInStringArray(tag_validator.IntType, fieldElem) {
		dataType = "integer"
		format = fieldElem
	} else if basic.ValidateStringContainInStringArray(tag_validator.FloatType, fieldElem) {
		dataType = "number"
		format = fieldElem
	} else if reflect.String.String() == fieldElem {
		dataType = "string"
	} else if fieldElem == "time.Time" {
		dataType = "string"
		format = "date-time"
	} else if reflect.Bool.String() == fieldElem {
		dataType = "boolean"
	}

	return
}

func RenameSwaggerSecurityName(
	param string,
) string {

	var sb strings.Builder
	for _, char := range param {
		if securityHeader.MatchString(string(char)) {
			sb.WriteRune(char)
		}
	}

	return sb.String()

}
